code.snippet:
body.t-clay .card,
body.t-clay .post,
body.t-clay .fact,
body.t-clay .contact-card,
body.t-clay .tag,
body.t-clay .btn,
body.t-clay .hero-badge,
body.t-clay .section-tag,
body.t-clay .contact-ico { border: 2px solid rgba(255,255,255,.6); }
body.t-clay .hero h1 { color: #4a4038; }
body.t-clay .tagline { color: #e07a5f; }
body.t-clay .section-tag { background: #f7f2ed; color: #e07a5f; font-weight: 700; }
body.t-clay .btn-primary {
  background: #e07a5f; color: #fff; text-shadow: 0 1px 2px rgba(150,70,50,.35);
  box-shadow:
    inset -3px -3px 8px rgba(255,255,255,.3),
    inset 3px 3px 8px rgba(150,70,50,.25),
    10px 10px 22px rgba(224,122,95,.35);
}
body.t-clay .btn-ghost { background: #f7f2ed; }
body.t-clay .btn-ghost:hover { color: #e07a5f; }
body.t-clay .card.featured { border-color: rgba(224,122,95,.5); }
body.t-clay .card.featured::before { background: #e07a5f; }
body.t-clay .card .star { color: #e07a5f; }
body.t-clay .lang { background: #efe6de; border: 1.5px solid rgba(255,255,255,.7); box-shadow: inset 2px 2px 5px rgba(74,64,56,.07); color: #94857a; }
body.t-clay .tag:hover { color: #e07a5f; }
body.t-clay .bar-track { background: #e8ded6; height: 14px; box-shadow: inset 4px 4px 9px rgba(74,64,56,.14), inset -3px -3px 7px rgba(255,255,255,.85); }
body.t-clay .bar-fill { background: linear-gradient(180deg, #eda287, #e07a5f); box-shadow: inset 0 2px 3px rgba(255,255,255,.5), 2px 2px 6px rgba(74,64,56,.12); }
body.t-clay .bar-row:nth-child(2) .bar-fill { background: linear-gradient(180deg, #9fc4b2, #81b29a); }
